-- ============================================================
-- 065: event + confession reminders
-- The "Event Reminders" and "Confession Reminders" switches existed but
-- nothing sent them. Both are generated by scheduled jobs; preferences are
-- honored by apply_notification_preferences(), pushes go out through the
-- notifications webhook as usual.
-- ============================================================

-- About 24 h before an event, remind people who said Going or Maybe (once).
CREATE OR REPLACE FUNCTION send_event_reminders()
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE n integer;
BEGIN
  INSERT INTO notifications (user_id, type, reference_id, message, actor_id, is_read)
  SELECT r.user_id, 'event_reminder', e.id,
         left('Tomorrow: ' || e.title || coalesce(' · ' || nullif(e.location, ''), ''), 300),
         NULL, false
  FROM events e
  JOIN event_rsvps r ON r.event_id = e.id AND r.response IN ('yes', 'maybe')
  WHERE e.start_time >  now() + interval '23 hours'
    AND e.start_time <= now() + interval '24 hours'
    AND NOT EXISTS (SELECT 1 FROM notifications n
                    WHERE n.user_id = r.user_id AND n.type = 'event_reminder' AND n.reference_id = e.id);
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;

-- Daily: people who use the confession tracker, once their chosen interval
-- has passed since their last confession — at most once per interval.
CREATE OR REPLACE FUNCTION send_confession_reminders()
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE n integer;
BEGIN
  INSERT INTO notifications (user_id, type, reference_id, message, actor_id, is_read)
  SELECT t.user_id, 'confession_reminder', NULL,
         'It has been ' || (current_date - t.last_date) || ' days since your last confession.',
         NULL, false
  FROM (SELECT user_id, max(confessed_at) AS last_date FROM confession_tracker GROUP BY user_id) t
  LEFT JOIN notification_preferences p ON p.user_id = t.user_id
  JOIN profiles pr ON pr.id = t.user_id AND pr.deleted_at IS NULL
  WHERE coalesce(p.confession_reminder, true)
    AND current_date - t.last_date >= coalesce(p.reminder_interval_days, 30)
    AND NOT EXISTS (SELECT 1 FROM notifications n
                    WHERE n.user_id = t.user_id AND n.type = 'confession_reminder'
                      AND n.created_at > now() - make_interval(days => coalesce(p.reminder_interval_days, 30)));
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;

REVOKE EXECUTE ON FUNCTION send_event_reminders(), send_confession_reminders() FROM PUBLIC, anon, authenticated;

SELECT cron.unschedule('event-reminders') WHERE EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'event-reminders');
SELECT cron.schedule('event-reminders', '5 * * * *', 'SELECT send_event_reminders()');

-- 14:00 UTC = 10 AM Eastern (9 AM in winter)
SELECT cron.unschedule('confession-reminders') WHERE EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'confession-reminders');
SELECT cron.schedule('confession-reminders', '0 14 * * *', 'SELECT send_confession_reminders()');
